const body = $('Webhook').first().json.body || {};
const id = String(body.version_id || '').trim();
const ok = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
return [{ json: {
  ok,
  version_id: id,
  fehler: ok ? [] : ['version_id fehlt oder ist ungültig']
} }];
